// === PILLAR 1: HMAC-SHA256 signature verification (defense at the edge) ===
// Verifies the incoming request was signed with the shared secret BEFORE any
// payload enters the pipeline. Secret comes from env only (rules.md Law 2).
// The Webhook node must have the "Raw Body" option ON so we hash the exact bytes
// the sender signed (JSON re-serialization would change the bytes and break HMAC).
const crypto = require('crypto');

const secret = $env.WEBHOOK_SIGNING_SECRET;
if (!secret) {
  throw new Error('WEBHOOK_SIGNING_SECRET is not set. Refusing to process unsigned traffic.');
}

const item = $input.first();
const headers = item.json.headers || {};
// Header format: "x-webhook-signature: sha256=<hex>"
const provided = String(headers['x-webhook-signature'] || '').replace(/^sha256=/, '');

// Recover the exact raw bytes the sender signed.
let raw;
const bin = item.binary && item.binary.data;
if (bin && bin.data) {
  raw = Buffer.from(bin.data, 'base64').toString('utf8');
} else {
  // Fallback if Raw Body is off — works for demos, but prefer Raw Body in prod.
  raw = typeof item.json.body === 'string' ? item.json.body : JSON.stringify(item.json.body || {});
}

const expected = crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('hex');

// Constant-time, length-guarded comparison (avoids timing side-channel).
let valid = false;
try {
  const a = Buffer.from(provided, 'hex');
  const b = Buffer.from(expected, 'hex');
  valid = a.length === b.length && crypto.timingSafeEqual(a, b);
} catch (e) {
  valid = false;
}

return [{
  json: {
    signatureValid: valid,
    payload: item.json.body,
    rawBody: raw,
    receivedAt: new Date().toISOString()
  }
}];

