// === PILLAR 2: strict JSON-schema validation of the LLM output ===
// Malformed / hallucinated model output is caught HERE and never propagates
// downstream. A thrown error routes the execution into the dead-letter path
// (rules.md Rule 4: enforce JSON Schema on any LLM output feeding systems).
// Formal schema: docs/json-schema.md. This is a dependency-free structural
// check (Ponytail rung 3 — stdlib/plain JS over a new npm dependency).
const res = $input.first().json;
const content = res && res.choices && res.choices[0] && res.choices[0].message
  ? res.choices[0].message.content
  : undefined;

if (content == null) {
  throw new Error('LLM returned no content (choices[0].message.content missing). Raw: ' + JSON.stringify(res).slice(0, 500));
}

let data;
try {
  data = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  throw new Error('LLM output is not valid JSON: ' + e.message);
}

const errors = [];
const isNonEmptyStr = v => typeof v === 'string' && v.length > 0;
const oneOf = (v, allowed) => allowed.includes(v);

if (!oneOf(data.category, ['bug', 'feature', 'question', 'abuse'])) errors.push('category must be bug|feature|question|abuse');
if (!oneOf(data.priority, ['low', 'medium', 'high'])) errors.push('priority must be low|medium|high');
if (!isNonEmptyStr(data.summary) || data.summary.length > 280) errors.push('summary must be a non-empty string <= 280 chars');
if (typeof data.confidence !== 'number' || data.confidence < 0 || data.confidence > 1) errors.push('confidence must be a number in [0,1]');

// additionalProperties: false — reject anything the schema did not declare.
const allowedKeys = ['category', 'priority', 'summary', 'confidence'];
for (const k of Object.keys(data)) {
  if (!allowedKeys.includes(k)) errors.push('unexpected key: ' + k);
}

if (errors.length) {
  throw new Error('Schema validation failed: ' + errors.join('; '));
}

return [{
  json: {
    valid: true,
    result: data,
    source: $('HMAC Signature Guard').first().json.payload
  }
}];

// === PILLAR 3: dead-letter record (self-contained + replayable) ===
// Every failure anywhere in the pipeline lands here. We build ONE structured
// record that (a) is alert-ready and (b) carries everything needed to replay.
// Replay options are documented in docs/dead-letter-and-replay.md.
const e = $input.first().json;
const wf = e.workflow || {};
const exec = e.execution || {};
const baseUrl = $env.N8N_BASE_URL || '';

const execUrl = (exec.id && wf.id && baseUrl)
  ? baseUrl.replace(/\/$/, '') + '/workflow/' + wf.id + '/executions/' + exec.id
  : null;

const record = {
  deadLetteredAt: new Date().toISOString(),
  workflow: { id: wf.id || null, name: wf.name || null },
  execution: {
    id: exec.id || null,
    url: execUrl,
    lastNode: exec.lastNodeExecuted || null
  },
  error: {
    message: (exec.error && exec.error.message) || 'unknown error',
    node: (exec.error && exec.error.node && exec.error.node.name) || exec.lastNodeExecuted || null
  },
  replay: 'Open execution URL -> Retry -> "Retry from failed node", OR re-POST the original signed payload to /secure-intake (the stored signature stays valid because HMAC covers the raw body).'
};

return [{ json: record }];
